# SPDX-License-Identifier: MIT
# Notes and tunes (traditional, public domain), and the instrument: on the board the Cortex-M4 plays
# them on D6 (mpy_m4.play), on time, while Python only hands over the score; in the LVGL MPY Studio
# simulator a stand-in follows the time without a sound.

import time

try:
    import mpy_m4

    HARDWARE = hasattr(mpy_m4, "play") and mpy_m4.available()
except ImportError:
    HARDWARE = False

NAMES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]


def hz(note):
    # "A4" -> 440, "C#5" -> 554, equal temperament; "-" -> 0, a rest.
    if note == "-":
        return 0
    name, octave = note[:-1], int(note[-1])
    semitones = NAMES.index(name) + 12 * (octave - 4) - 9
    return round(440 * 2 ** (semitones / 12))


# (note, beats)
TUNES = {
    "Ode to Joy": [("E4", 1), ("E4", 1), ("F4", 1), ("G4", 1), ("G4", 1), ("F4", 1), ("E4", 1), ("D4", 1),
                   ("C4", 1), ("C4", 1), ("D4", 1), ("E4", 1), ("E4", 1.5), ("D4", 0.5), ("D4", 2),
                   ("E4", 1), ("E4", 1), ("F4", 1), ("G4", 1), ("G4", 1), ("F4", 1), ("E4", 1), ("D4", 1),
                   ("C4", 1), ("C4", 1), ("D4", 1), ("E4", 1), ("D4", 1.5), ("C4", 0.5), ("C4", 2)],
    "Frere Jacques": [("C4", 1), ("D4", 1), ("E4", 1), ("C4", 1), ("C4", 1), ("D4", 1), ("E4", 1), ("C4", 1),
                      ("E4", 1), ("F4", 1), ("G4", 2), ("E4", 1), ("F4", 1), ("G4", 2),
                      ("G4", 0.5), ("A4", 0.5), ("G4", 0.5), ("F4", 0.5), ("E4", 1), ("C4", 1),
                      ("G4", 0.5), ("A4", 0.5), ("G4", 0.5), ("F4", 0.5), ("E4", 1), ("C4", 1),
                      ("C4", 1), ("G3", 1), ("C4", 2), ("C4", 1), ("G3", 1), ("C4", 2)],
    "Twinkle": [("C4", 1), ("C4", 1), ("G4", 1), ("G4", 1), ("A4", 1), ("A4", 1), ("G4", 2),
                ("F4", 1), ("F4", 1), ("E4", 1), ("E4", 1), ("D4", 1), ("D4", 1), ("C4", 2),
                ("G4", 1), ("G4", 1), ("F4", 1), ("F4", 1), ("E4", 1), ("E4", 1), ("D4", 2),
                ("G4", 1), ("G4", 1), ("F4", 1), ("F4", 1), ("E4", 1), ("E4", 1), ("D4", 2)],
}


def score(tune, beat_ms):
    # (Hz, ms) pairs, each note followed by a short rest so that repeated notes are heard apart.
    notes = []
    for note, beats in TUNES[tune]:
        length = int(beats * beat_ms)
        notes.append((hz(note), length - 30))
        notes.append((0, 30))
    return notes


class Board:
    def play(self, notes):
        mpy_m4.play(notes)

    def playing(self):
        return mpy_m4.playing()

    def measure(self):
        return mpy_m4.measure("D6", 60)


class Simulated:
    def __init__(self):
        self._notes = []
        self._start = 0

    def play(self, notes):
        self._notes = list(notes)
        self._start = time.ticks_ms()

    def playing(self):
        elapsed = time.ticks_diff(time.ticks_ms(), self._start)
        for i, (frequency, ms) in enumerate(self._notes):
            if elapsed < ms:
                return i
            elapsed -= ms
        return None

    def measure(self):
        i = self.playing()
        return (float(self._notes[i][0]), 0.5) if i is not None and self._notes[i][0] else (0.0, 0.0)


instrument = Board() if HARDWARE else Simulated()
